// Spring Boot configuration with resource tags for cost tracking
@Configuration
public class AwsResourceConfig {

    @Bean
    public AmazonEC2 ec2Client() {
        return AmazonEC2ClientBuilder.standard()
            .withRegion(Regions.US_EAST_1)
            .build();
    }

    // Tag resources with team and environment for cost allocation
    public void tagInstance(String instanceId, String team, String env) {
        var ec2 = ec2Client();

        var tags = List.of(
            new Tag("Team", team),        // Track which team owns this cost
            new Tag("Environment", env),  // Identify dev vs prod
            new Tag("AutoShutdown", env.equals("dev") ? "yes" : "no")
        );

        var request = new CreateTagsRequest()
            .withResources(instanceId)
            .withTags(tags);

        ec2.createTags(request);  // AWS Cost Explorer groups by these tags
    }
}

// Spring Cloud Function handler for AWS Lambda
@SpringBootApplication
public class OrderProcessorFunction {
    @Bean
    public Function<OrderEvent, OrderResult> processOrder() {
        return event -> {
            // Lambda invokes this function for each event
            var orderId = event.orderId();
            var items = event.items();

            // Business logic runs without managing servers
            double total = items.stream().map(Item::price).reduce(0.0, Double::sum);

            return new OrderResult(orderId, total, "PROCESSED");
        };
    }
}

record OrderEvent(String orderId, List<Item> items) {}
record Item(String name, double price) {}
record OrderResult(String orderId, double total, String status) {}

// application.yml with environment variable substitution
spring:
  datasource:
    url: ${DATABASE_URL}  // Factor III: store config in environment
    username: ${DB_USER}
    password: ${DB_PASSWORD}
  profiles:
    active: ${SPRING_PROFILE:dev}  // default to dev if not set

logging:
  pattern:
    console: "%d{yyyy-MM-dd HH:mm:ss} - %msg%n"  // Factor XI: logs to stdout

@RestController
public class OrderController {
    private final OrderRepository orderRepo;  // Factor IV: explicit dependency

    // Factor VI: stateless process - no session state in memory
    @PostMapping("/orders")
    public OrderResponse createOrder(@RequestBody OrderRequest request) {
        var order = new Order(request.userId(), request.items());
        orderRepo.save(order);  // Factor XII: state in database, not local variables
        return new OrderResponse(order.id(), "CREATED");
    }
}
